// @ts-check
// Single source of truth for the whole video: timing, on-screen captions,
// and the voiceover narration. Both the Remotion compositions and the
// ElevenLabs generator (scripts/generate-voiceover.mjs) import from here, so
// captions and audio can never drift out of sync.
//
// Fields per scene:
//   id            unique id; also the audio filename stem (audio/<id>.mp3)
//   tag           short uppercase label shown in the step chip
//   clip          screen-recording file under public/ (or null for placeholder)
//   audio         voiceover file under public/ (generated by the TTS script)
//   seconds       fallback duration; the real audio length overrides it if longer
//   captions      short, title-style lines shown on screen (word-by-word reveal)
//   narration     what the AI voice actually says (richer than the captions)
//   accent        IBM Carbon accent key (see theme/ibm.ts ACCENTS) — chrome only,
//                 never green/red (those stay reserved for pro/against in-app)

export const FPS = 30;
export const WIDTH = 1920;
export const HEIGHT = 1080;

// Silence padding added after each voiceover line so cuts don't clip speech.
export const PAD_AFTER_AUDIO = 0.7;

// On-screen / spoken product name for the video (may differ from the repo name).
export const BRAND = "Argora";
export const DOMAIN = "argora.app";

